-- Rifts World Book 34: Northern Gun Two, the separately priced Demon Slayer Techno-Wizard conversions and Enforcer Guardsman helmet camera (printed 88 and 92)
-- 8 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~304-northern-gun-2-power-armor-c-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-x44-demon-slayer-tw-lightning-bolt-discharger', 'TW Forearm Lightning Bolt Discharger (Demon Slayer)', 'rifts', 'weapon', NULL, 245000, '245,000 credits. Aftermarket Techno-Wizard work; Northern Gun never builds or sells it.', '3D6 M.D. per electrical bolt', 1, '500 ft (152 m)', '12 blasts; 32 P.P.E. or 64 I.S.P. restores six', 'Single shot; each blast counts as one melee attack', NULL, NULL, NULL, 'Optional Techno-Wizard upgrade for the Demon Slayer power armor: its forearm plasma blaster rebuilt to throw bolts of electricity. Anti-monster and anti-demon, secondarily defense; best against demons vulnerable to electricity. Shops in the Federation of Magic, the Colorado Baronies, Lazlo and New Lazlo do the work, usually reusing the original weapon for parts. Recharging needs a wearer or teammate with P.P.E. or I.S.P.', 'Rifts World Book 34: Northern Gun Two p.88', NULL),
  ('ng-x44-demon-slayer-tw-fire-ball-discharger', 'TW Forearm Fire Ball Discharger (Demon Slayer)', 'rifts', 'weapon', NULL, 195000, '195,000 credits. Aftermarket Techno-Wizard work; Northern Gun never builds or sells it.', '4D6 M.D. per fire ball', 1, '500 ft (152 m)', '12 fire balls; 25 P.P.E. or 50 I.S.P. restores three', 'One fire ball at a time; each counts as one melee attack', NULL, NULL, NULL, 'Optional Techno-Wizard upgrade for the Demon Slayer power armor: the forearm plasma blaster converted to launch a fire ball that swells to basketball size before it hits. Anti-monster and anti-demon, secondarily assault and defense. Meant for creatures vulnerable to fire, though most demons of Hades are immune to it. Recharging needs a wearer or teammate with P.P.E. or I.S.P.', 'Rifts World Book 34: Northern Gun Two p.88', NULL),
  ('ng-x44-demon-slayer-tw-light-fire-bolt-gatling', 'TW Weapon Arm Light Fire Bolt Gatling Gun (Demon Slayer)', 'rifts', 'weapon', NULL, 350000, '350,000 credits per weapon arm with its TW power supply. Aftermarket Techno-Wizard work; Northern Gun never builds or sells it.', '2D6 M.D. per blast', 1, '1,000 ft (305 m)', '48 fire bolts per arm; 40 P.P.E. or 80 I.S.P. restores 12', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Optional Techno-Wizard upgrade for one of the Demon Slayer power armor''s robot gatling arms, firing small bolts of fire in place of silver and wood rounds. Anti-monster and anti-demon, secondarily assault and defense. Recharging needs a wearer or teammate with P.P.E. or I.S.P.', 'Rifts World Book 34: Northern Gun Two p.88', NULL),
  ('ng-x44-demon-slayer-tw-heavy-fire-bolt-gatling', 'TW Weapon Arm Heavy Fire Bolt Gatling Gun (Demon Slayer)', 'rifts', 'weapon', NULL, 500000, '500,000 credits per weapon arm with its TW power supply. Aftermarket Techno-Wizard work; Northern Gun never builds or sells it.', '4D6 M.D. per blast', 1, '1,000 ft (305 m)', '24 fire bolts per arm; 40 P.P.E. or 80 I.S.P. restores six', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Optional Techno-Wizard upgrade for one of the Demon Slayer power armor''s robot gatling arms, trading ammunition for heavier bolts of fire and a smaller charge. Anti-monster and anti-demon, secondarily assault and defense. Recharging needs a wearer or teammate with P.P.E. or I.S.P.', 'Rifts World Book 34: Northern Gun Two p.88', NULL),
  ('ng-x44-demon-slayer-tw-wood-shard-gatling', 'TW Weapon Arm Wood Shard Gatling Gun (Demon Slayer)', 'rifts', 'weapon', NULL, 350000, '350,000 credits per weapon arm with its TW power supply. Aftermarket Techno-Wizard work; Northern Gun never builds or sells it.', '3D6 S.D.C. per burst of six wood shards', 0, '1,200 ft (366 m)', '72 bursts per arm; 40 P.P.E. or 80 I.S.P. restores eight', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'Optional Techno-Wizard upgrade for one of the Demon Slayer power armor''s robot gatling arms that conjures and fires splinters of wood, each about half a used pencil long and twice as thick, for vampires and other beings vulnerable to wood. Anti-monster and anti-demon, secondarily assault and defense. Recharging needs a wearer or teammate with P.P.E. or I.S.P.', 'Rifts World Book 34: Northern Gun Two p.88', NULL),
  ('ng-x44-demon-slayer-tw-ice-shard-discharger', 'TW Forearm Ice Shard Discharger (Demon Slayer)', 'rifts', 'weapon', NULL, 275000, '275,000 credits. Aftermarket Techno-Wizard work; Northern Gun never builds or sells it.', '2D6 M.D. per burst of three ice shards', 1, '500 ft (152 m)', '12 bursts; 25 P.P.E. or 50 I.S.P. restores four', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'Optional Techno-Wizard upgrade for the Demon Slayer power armor: the forearm plasma blaster converted to spit bursts of ice shards. Anti-monster and anti-demon, secondarily assault and defense. Recharging needs a wearer or teammate with P.P.E. or I.S.P.', 'Rifts World Book 34: Northern Gun Two p.88', NULL),
  ('ng-x44-demon-slayer-tw-ice-shard-gatling', 'TW Weapon Arm Ice Shard Gatling Gun (Demon Slayer)', 'rifts', 'weapon', NULL, 580000, '580,000 credits per weapon arm with its TW power supply. Aftermarket Techno-Wizard work; Northern Gun never builds or sells it.', '4D6 M.D. per burst of six ice shards', 1, '1,000 ft (305 m)', '24 bursts per arm; 40 P.P.E. or 80 I.S.P. restores four', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'Optional Techno-Wizard upgrade for one of the Demon Slayer power armor''s robot gatling arms, magically firing bursts of ice shards in place of ammunition. Anti-monster and anti-demon, secondarily assault and defense. Recharging needs a wearer or teammate with P.P.E. or I.S.P.', 'Rifts World Book 34: Northern Gun Two p.88', NULL),
  ('ng-xp54-advanced-helmet-camera', 'Advanced Helmet Camera (Enforcer Guardsman)', 'rifts', 'gear', NULL, 15000, '15,000 credits as an extra-cost option for the Enforcer Guardsman police power armor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 8, 'An optional full video camera for the Enforcer Guardsman, fitted to the helmet or a shoulder. It adds a telescopic zoom (2 miles/3.2 km) and a x12 macro lens for surveillance, recording police work and close-up evidence, and can send stills and video live to a command post or station up to 5 miles (8 km) away unboosted while recording to its data card (96 hours of video, 10,000 stills). A small target that needs a Called Shot to hit. If it is destroyed, an Operator or computer or communications specialist has a 01-50% chance to recover 1D6x10% of the stored footage.', 'Rifts World Book 34: Northern Gun Two p.92', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 8 gear rows are in' AS assertion, count(*) AS got, 8 AS want
  FROM gear WHERE slug IN ('ng-x44-demon-slayer-tw-lightning-bolt-discharger', 'ng-x44-demon-slayer-tw-fire-ball-discharger', 'ng-x44-demon-slayer-tw-light-fire-bolt-gatling', 'ng-x44-demon-slayer-tw-heavy-fire-bolt-gatling', 'ng-x44-demon-slayer-tw-wood-shard-gatling', 'ng-x44-demon-slayer-tw-ice-shard-discharger', 'ng-x44-demon-slayer-tw-ice-shard-gatling', 'ng-xp54-advanced-helmet-camera') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
